import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.BsgK4TUM.js";const m=JSON.parse('{"title":"CLI Commands","description":"","frontmatter":{},"headers":[],"relativePath":"developers/cli-commands.md","filePath":"developers/cli-commands.md"}'),r={name:"developers/cli-commands.md"};function c(i,e,s,l,n,p){return a(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="cli-commands" tabindex="-1">CLI Commands <a class="header-anchor" href="#cli-commands" aria-label="Permalink to &quot;CLI Commands&quot;">​</a></h1><p>See the <a href="http://documentation.concretecms.org/developers/appendix/cli-commands" target="_blank" rel="noreferrer">Concrete CMS documentation covering how to run CLI commands</a></p><h2 id="reset-store-data" tabindex="-1">Reset Store Data <a class="header-anchor" href="#reset-store-data" aria-label="Permalink to &quot;Reset Store Data&quot;">​</a></h2><p>A CLI command is available to clear all orders, products, discounts or all three at once. This command is useful if you have been testing an install and wish to clear test data before go-live.</p><pre><code>cstore:reset [&lt;type&gt;]
</code></pre><p>Where the type options are:</p><ul><li><code>orders</code></li><li><code>order-number [number]</code></li><li><code>products</code></li><li><code>discounts</code></li><li><code>all</code> - combining all four options above</li></ul><p>The <code>order-number</code> option will reset the next order number that will be allocated. This option defaults to 1, but a number can be specified as additional argument, e.g.:</p><pre><code>cstore:reset order-number 1000
</code></pre><h2 id="update-product-quantities-from-variations" tabindex="-1">Update Product Quantities From Variations <a class="header-anchor" href="#update-product-quantities-from-variations" aria-label="Permalink to &quot;Update Product Quantities From Variations&quot;">​</a></h2><p>For products with variations, updates the product&#39;s stock quantity from the quantities of its variations.</p><pre><code>cstore:product:quantity:update [--all] [--product=&lt;ID&gt;] [--force]
</code></pre><p>Use <code>--all</code> to update all products with variations, or <code>--product</code> (repeatable) to limit it to specific product IDs. <code>--force</code> runs the update even if automatic product quantities are disabled.</p><h2 id="update-product-image-titles" tabindex="-1">Update Product Image Titles <a class="header-anchor" href="#update-product-image-titles" aria-label="Permalink to &quot;Update Product Image Titles&quot;">​</a></h2><p>Updates the titles of product image files.</p><pre><code>cstore:product:image:info:update [--all] [--product=&lt;ID&gt;] [--title=&lt;operation&gt;] [--flags=&lt;flag&gt;] [--yes]
</code></pre><p>The <code>--title</code> option can be:</p><ul><li><code>keep</code> - use the file titles</li><li><code>cleanup</code> - use the file titles, removing any file extensions and replacing underscores with spaces</li><li><code>prodname-once</code> - match the product name, if the file title has not been altered since upload</li><li><code>prodname-always</code> - always match the product name</li></ul><p>The <code>--flags</code> option selects which images to update: <code>1</code> for primary product images, <code>2</code> for secondary product images, and <code>4</code> for variation images.</p><h2 id="update-product-page-metadata" tabindex="-1">Update Product Page Metadata <a class="header-anchor" href="#update-product-page-metadata" aria-label="Permalink to &quot;Update Product Page Metadata&quot;">​</a></h2><p>Updates the metadata of product pages.</p><pre><code>cstore:product:page:metadata:update [--all] [--product=&lt;ID&gt;] [--flags=&lt;flag&gt;] [--yes]
</code></pre><p>The <code>--flags</code> option selects what to update: <code>1</code> to update page descriptions, and <code>2</code> to update page OpenGraph meta tags.</p><p>For each command, <code>--yes</code> runs the operation without asking for confirmation. Run <code>concrete help &lt;command&gt;</code> for the full list of options.</p>`,24)])])}const h=t(r,[["render",c]]);export{m as __pageData,h as default};
